#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(a: i64, b: i64) -> bool { a == 0 && b == 1 }

    #[effects(pure)]
    #[uses(witness, tasks::below, tasks::strictly_between)]
    fn refute(a: i64, b: i64) -> ()
        requires witness(a, b),
        ensures never(),
    {
        let r: i64 = tasks::between(a, b);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(0, 1)
    }
}

